class Solution {
    public int minimumOperations(int[] nums) {
        int i = 0, j = nums.length - 1, ops = 0;
        long a = nums[i], b = nums[j];
        while (i < j) {
            if (a == b) {
                a = nums[++i];
                b = nums[--j];
            } else if (a < b) {
                a += nums[++i];
                ops++;
            } else {
                b += nums[--j];
                ops++;
            }
        }
        return ops;
    }
}
